/// A pure specification: returns true exactly when there is
/// some index i with i + 1 < a.len() and a[i] + 1 == a[i+1].
#[spec]
fn contains_consecutive_numbers_spec(a: Seq<i32>) -> bool {
    exists(|i: nat| i + 1 < a.len() && a[i] + 1 == a[i + 1])
}

//----------------------------------------------------------------------------
// IMPLEMENTATION
//----------------------------------------------------------------------------

#[verifier::external_body]
#[requires(true)]
#[ensures(ret == contains_consecutive_numbers_spec(a@))]
pub fn contains_consecutive_numbers(a: &[i32]) -> bool {
    // Original implementation unchanged
    a.windows(2).any(|w| w[0] + 1 == w[1])
}

